        edges.push({ from: prev.id, to: node.id });
        prev = node;
      }
      continue;
    } else if (/^if\s+/.test(line)) {
      currentType = "decision";
      shape = "diamond";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      edges.push({ from: prev.id, to: node.id });
      decisionStack.push({ node: node, hasElse: false, prev: prev });
      prev = node;
    } else if (/^elif\s+/.test(line)) {
      currentType = "decision";
      shape = "diamond";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      const lastDecision = decisionStack[decisionStack.length - 1];
      if (lastDecision) {
        edges.push({ from: lastDecision.node.id, to: node.id, label: "No" });
      }
      decisionStack.push({ node: node, hasElse: false, prev: lastDecision.node });
      prev = node;
    } else if (/^else[:\{]?$/.test(line)) {
      const lastDecision = decisionStack[decisionStack.length - 1];
      if (lastDecision) {
        lastDecision.hasElse = true;
      }
      continue;
    } else if (/^(for|while)\s+/.test(line)) {
      currentType = "loop";
      shape = "diamond";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      edges.push({ from: prev.id, to: node.id });
      loopNode = node;
      prev = node;
    } else if (/print\(|console\.log\(|System\.out\.println\(|printf\(|cout/.test(line)) {
      currentType = "output";
      shape = "parallelogram";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      
      // Handle edges based on decision context
      if (decisionStack.length > 0) {
        const lastDecision = decisionStack[decisionStack.length - 1];
        const edgeLabel = lastDecision.hasElse ? "No" : "Yes";
        edges.push({ from: prev.id, to: node.id, label: edgeLabel });
      } else {
        edges.push({ from: prev.id, to: node.id });
      }
      prev = node;
    } else if (/(\w+)\([^)]*\)/.test(line) && !line.startsWith('if')) {
      currentType = "process";
      shape = "rectangle";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      
      if (decisionStack.length > 0 && loopNode) {
        edges.push({ from: loopNode.id, to: node.id, label: "Yes" });
      } else {
        edges.push({ from: prev.id, to: node.id });
      }
      prev = node;
    } else if (/^return\b/.test(line)) {
      currentType = "output";
      shape = "parallelogram";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      edges.push({ from: prev.id, to: node.id });
      prev = node;
    }
  }

  // Add End node
  const endNode = { 
    id: id++, 
    text: 'End', 
    type: 'end',
    shape: 'terminal',
    lineNumber: lines.length
  };
  nodes.push(endNode);
  if (prev) {
    edges.push({ from: prev.id, to: endNode.id });
  }

  return { nodes, edges };
}

function parseSQLToGraph(code) {
  const nodes = [];
  const edges = [];
  let id = 1;

  // Start
  nodes.push({
    id: id++,
    text: 'Start',
    type: 'start',
    shape: 'terminal',
    lineNumber: 1
  });

  let prev = nodes[0];

  // Parse SELECT statement
  if (/SELECT/i.test(code)) {
    const selectMatch = code.match(/SELECT\s+(.+?)\s+FROM/is);
    const columns = selectMatch ? selectMatch[1].trim() : '*';
    
    const node = {
      id: id++,
      text: `Select columns: ${columns}`,
      type: 'input',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse FROM clause
  if (/FROM/i.test(code)) {
    const fromMatch = code.match(/FROM\s+(\w+)/i);
    const table = fromMatch ? fromMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `From table: ${table}`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse WHERE clause
  if (/WHERE/i.test(code)) {
    const whereMatch = code.match(/WHERE\s+(.+?)(?:;|$)/is);
    const condition = whereMatch ? whereMatch[1].trim().replace(/;/g, '') : 'condition';
    
    const node = {
      id: id++,
      text: `Filter: ${condition}`,
      type: 'decision',
      shape: 'diamond',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse INSERT
  if (/INSERT/i.test(code)) {
    const insertMatch = code.match(/INSERT\s+INTO\s+(\w+)/i);
    const table = insertMatch ? insertMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `Insert into: ${table}`,
      type: 'output',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse UPDATE
  if (/UPDATE/i.test(code)) {
    const updateMatch = code.match(/UPDATE\s+(\w+)/i);
    const table = updateMatch ? updateMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `Update table: ${table}`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse DELETE
  if (/DELETE/i.test(code)) {
    const deleteMatch = code.match(/DELETE\s+FROM\s+(\w+)/i);
    const table = deleteMatch ? deleteMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `Delete from: ${table}`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }  // Result
  const resultNode = {
    id: id++,
    text: 'Return results',
    type: 'output',
    shape: 'parallelogram',
    lineNumber: 1
  };
  nodes.push(resultNode);
  edges.push({ from: prev.id, to: resultNode.id });

  // End
  const endNode = { 
    id: id++, 
    text: 'End', 
    type: 'end',
    shape: 'terminal',
    lineNumber: 1
  };
  nodes.push(endNode);
  edges.push({ from: resultNode.id, to: endNode.id });

  return { nodes, edges };
}

function parseHTMLToGraph(code) {
  const nodes = [];
  const edges = [];
  let id = 1;

  // Start
  nodes.push({ 
    id: id++, 
    text: 'Start', 
    type: 'start',
    shape: 'terminal',
    lineNumber: 1
  });

  let prev = nodes[0];

  // Parse HTML structure
  if (/<html/i.test(code)) {
    const node = {
      id: id++,
      text: 'Create HTML document',
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse head section
  if (/<head/i.test(code)) {
    const titleMatch = code.match(/<title>(.+?)<\/title>/i);
    const title = titleMatch ? titleMatch[1] : 'Document';
    
    const node = {
      id: id++,
      text: `Set title: "${title}"`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse body section
  if (/<body/i.test(code)) {
    const node = {
      id: id++,
      text: 'Create body content',
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse headings
  const h1Match = code.match(/<h1[^>]*>(.+?)<\/h1>/i);
  if (h1Match) {
    const node = {
      id: id++,
      text: `Display heading: "${h1Match[1]}"`,
      type: 'output',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse paragraphs
  const pMatches = code.match(/<p[^>]*>(.+?)<\/p>/gi);
  if (pMatches && pMatches.length > 0) {
    const node = {
      id: id++,
      text: `Display ${pMatches.length} paragraph(s)`,
      type: 'output',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse styles
  if (/<style/i.test(code) || /style=/i.test(code)) {
    const node = {
      id: id++,
      text: 'Apply CSS styling',
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Render output
  const renderNode = {
    id: id++,
    text: 'Render webpage',
    type: 'output',
    shape: 'parallelogram'
  };
  nodes.push(renderNode);
  edges.push({ from: prev.id, to: renderNode.id });

  // End
  const endNode = { 
    id: id++, 
    text: 'End', 
    type: 'end',
    shape: 'terminal'
  };
  nodes.push(endNode);
  edges.push({ from: renderNode.id, to: endNode.id });

  return { nodes, edges };
}

